export type Deliver = 'fill' | 'submit'

export type Config = {
  deliver: Deliver
  compactInstructions: string
  copyToClipboard: boolean
  /** Where handoff notes go; empty for the system temp directory's claude-relay/. */
  noteDir: string
}

/**
 * idle: nothing running. saving: the save turn was submitted and hasn't
 * ended. continuing: the save turn ended; forking, compacting, delivering.
 */
export type Phase = 'idle' | 'saving' | 'continuing'

export type Run = {
  phase: Phase
  /** Bumped on every start and cancel, so a stale continuation stops itself. */
  runId: number
  /** The save turn's id, once its turn.start is seen. */
  saveTurnId: string | null
  startedAt: number | null
  /** Where the save turn's final message (the handoff note) is written. */
  notePath: string | null
}

/** The last continuation prompt, kept in $.store across sessions for /relay paste. */
export type SavedPrompt = {
  text: string
  at: number
  sessionId: string
}

export type Command =
  | { kind: 'start'; focus: string }
  | { kind: 'status' }
  | { kind: 'cancel' }
  | { kind: 'paste' }

declare module 'claude-code' {
  interface PluginState {
    relay: { run: Run }
  }
}
